using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;

namespace App.Entities;

/// <summary>A document of the "customers" collection.</summary>
[BsonIgnoreExtraElements]
public class Customer
{
    [BsonId]
    [BsonRepresentation(BsonType.ObjectId)]
    public string Id { get; set; } = null!;

    [BsonElement("email")]
    public string Email { get; set; } = null!;

    [BsonElement("name")]
    public string Name { get; set; } = null!;

    [BsonElement("age")]
    [BsonIgnoreIfNull]
    public long? Age { get; set; }

    [BsonElement("balance")]
    [BsonRepresentation(BsonType.Decimal128)]
    [BsonIgnoreIfNull]
    public decimal? Balance { get; set; }

    [BsonElement("visits")]
    [BsonIgnoreIfNull]
    public long? Visits { get; set; }

    [BsonElement("rate")]
    public double Rate { get; set; }

    [BsonElement("active")]
    public bool Active { get; set; }

    [BsonElement("address")]
    public Customer.AddressDocument Address { get; set; } = null!;

    [BsonElement("tags")]
    public List<string> Tags { get; set; } = null!;

    [BsonElement("seen")]
    [BsonIgnoreIfNull]
    public DateTime? Seen { get; set; }

    [BsonElement("ref")]
    [BsonGuidRepresentation(GuidRepresentation.Standard)]
    [BsonIgnoreIfNull]
    public Guid? Ref { get; set; }

    [BsonElement("photo")]
    [BsonIgnoreIfNull]
    public byte[]? Photo { get; set; }

    [BsonElement("scores")]
    [BsonIgnoreIfNull]
    public MongoDB.Bson.BsonValue? Scores { get; set; }

    [BsonElement("mixed")]
    [BsonIgnoreIfNull]
    public MongoDB.Bson.BsonValue? Mixed { get; set; }

    [BsonElement("nothing")]
    [BsonIgnoreIfNull]
    public MongoDB.Bson.BsonValue? Nothing { get; set; }

    [BsonElement("empty")]
    [BsonIgnoreIfNull]
    public List<MongoDB.Bson.BsonValue>? Empty { get; set; }

    [BsonElement("deletedAt")]
    [BsonIgnoreIfNull]
    public DateTime? DeletedAt { get; set; }

    /// <summary>A nested document: it is stored with the one that holds it.</summary>
    [BsonIgnoreExtraElements]
    public class AddressDocument
    {
        [BsonElement("street")]
        public string Street { get; set; } = null!;

        [BsonElement("city")]
        public string City { get; set; } = null!;

        [BsonElement("zip code")]
        [BsonIgnoreIfNull]
        public string? ZipCode { get; set; }
    }
}

