    [BsonElement("customer")]
    [BsonRepresentation(BsonType.ObjectId)]
    [BsonIgnoreIfNull]
    public string? Customer { get; set; }

    [BsonElement("seller")]
    [BsonRepresentation(BsonType.ObjectId)]
    [BsonIgnoreIfNull]
    public string? Seller { get; set; }

    [BsonElement("lines")]
    [BsonIgnoreIfNull]
    public List<Order.LineDocument>? Lines { get; set; }

    /// <summary>Gives an identifier to the documents of its lists that have none: MongoDB numbers only whole documents.</summary>
    public void IdentifyItems()
    {
        foreach (var item in Lines ?? []) item.Id ??= ObjectId.GenerateNewId().ToString();
    }

    /// <summary>A nested document: it is stored with the one that holds it.</summary>
    [BsonIgnoreExtraElements]
    public class LineDocument
    {
        [BsonId]
        [BsonRepresentation(BsonType.ObjectId)]
        [BsonIgnoreIfNull]
        public string? Id { get; set; }

        [BsonElement("product")]
        [BsonIgnoreIfNull]
        public Order.LineDocument.ProductDocument? Product { get; set; }

        [BsonElement("quantity")]
        [BsonIgnoreIfNull]
        public long? Quantity { get; set; }

        [BsonElement("note")]
        [BsonIgnoreIfNull]
        public string? Note { get; set; }

        /// <summary>A nested document: it is stored with the one that holds it.</summary>
        [BsonIgnoreExtraElements]
        public class ProductDocument
        {
            [BsonElement("sku")]
            [BsonIgnoreIfNull]
            public string? Sku { get; set; }

            [BsonElement("price")]
            [BsonRepresentation(BsonType.Decimal128)]
            [BsonIgnoreIfNull]
            public decimal? Price { get; set; }
        }
    }
}

