namespace App.Services;

/// <summary>Operations on orders. Repositories commit every write.</summary>
public class OrderService(IUnitOfWork unitOfWork)
{
    private readonly IUnitOfWork uow = unitOfWork;

    /// <summary>Checks the values against the rules of the "orders" table, and the rows they point to; throws ValidationFailedException with every problem.</summary>
    private static async Task ValidateAsync(IUnitOfWork uow, Dictionary<string, object?> values, Order? current)
    {
        var creating = current is null;
        var errors = new List<FieldError>();
        {
            var value = values.GetValueOrDefault("Lines");
            if (value is not null)
            {
                var document = (List<Order.LineDocument>)value;
                if (document is not null)
                {
                    for (var i0 = 0; i0 < document.Count; i0++)
                    {
                        if (document[i0] is null) errors.Add(new FieldError("lines" + "." + i0, "is required"));
                        else CheckLine(document[i0], "lines" + "." + i0, errors);
                    }
                }
            }
        }
        {
            var customer = values.TryGetValue("Customer", out var givenCustomer) ? (string?)givenCustomer : current?.Customer;
            if (customer is not null && await uow.Customers.FindByIdAsync(customer) is null)
                errors.Add(new FieldError("customer", "no Customer has this key"));
        }
        if (errors.Count > 0) throw new ValidationFailedException("Order", errors);
    }

    /// <summary>Every check before a write: the values, the rows they point to, the unique values.</summary>
    private static async Task CheckAsync(IUnitOfWork uow, Dictionary<string, object?> values, Order? current)
    {
        await ValidateAsync(uow, values, current);
    }

    /// <summary>Sets the given values on the entity.</summary>
    private static void Apply(Order entity, Dictionary<string, object?> values)
    {
        if (values.TryGetValue("Number", out var number)) entity.Number = (long?)number;
        if (values.TryGetValue("Customer", out var customer)) entity.Customer = (string?)customer;
        if (values.TryGetValue("Seller", out var seller)) entity.Seller = (string?)seller;
        if (values.TryGetValue("Lines", out var lines)) entity.Lines = (List<Order.LineDocument>?)lines;
    }

    /// <summary>The Order with this key; NotFoundException when there is none.</summary>
    private static async Task<Order> FindAsync(IUnitOfWork uow, string id) =>
        await uow.Orders.FindByIdAsync(id) ?? throw new NotFoundException("Order", id);

    /// <summary>The values an update gives, by field.</summary>
    private static Dictionary<string, object?> Given(OrderChanges changes)
    {
        var values = new Dictionary<string, object?>();
        if (changes.Number is { IsPresent: true } number) values["Number"] = number.Value;
        if (changes.Customer is { IsPresent: true } customer) values["Customer"] = customer.Value;
        if (changes.Seller is { IsPresent: true } seller) values["Seller"] = seller.Value;
        if (changes.Lines is { IsPresent: true } lines) values["Lines"] = lines.Value;
        return values;
    }

    /// <summary>What a Order.LineDocument does not follow of its rules, each with the path of its field.</summary>
    private static void CheckLine(Order.LineDocument value, string path, List<FieldError> errors)
    {
        if (value.Product is not null) CheckLineProduct(value.Product, path + ".product", errors);
    }

    /// <summary>What a Order.LineDocument.ProductDocument does not follow of its rules, each with the path of its field.</summary>
    private static void CheckLineProduct(Order.LineDocument.ProductDocument value, string path, List<FieldError> errors)
    {
    }

    /// <summary>Stores a new Order after checking it.</summary>
    public async Task<Order> CreateOrderAsync(Order order)
    {
        var values = new Dictionary<string, object?>();
        if (order.Number is not null) values["Number"] = order.Number;
        if (order.Customer is not null) values["Customer"] = order.Customer;
        if (order.Seller is not null) values["Seller"] = order.Seller;
        if (order.Lines is not null) values["Lines"] = order.Lines;
        return await this.uow.TransactionAsync(async uow =>
        {
            await CheckAsync(uow, values, null);
            return await uow.Orders.InsertAsync(order);
        });
    }

    /// <summary>The Order with this key; NotFoundException when there is none.</summary>
