    /// <summary>Adds an item to lines.</summary>
    public async Task<Order> AddLineAsync(string id, Order.LineDocument line)
    {
        var errors = new List<FieldError>();
        CheckLine(line, "lines", errors);
        if (errors.Count > 0) throw new ValidationFailedException("Order", errors);
        return await this.uow.TransactionAsync(async uow =>
        {
            await FindAsync(uow, id);
            return await uow.Orders.AddLineAsync(id, line) ?? throw new NotFoundException("Order", id);
